PRAGMA defer_foreign_keys=TRUE;

INSERT OR IGNORE INTO "guides" ("id","equipment_id","title","author_email","author_phone","symptom","safety_ppe","tools_required","introduction","status","is_approved","created_at") VALUES('eb134d2a-210e-4e52-a487-a5b4a7b9ee58','b7d91f28-8630-4e92-ba53-96e510ac2749','rescue boat starting battery replacement','dhanushkumar.chandrasekaran1@gmail.com','9092391398','Routine planned maintenance (PMS) renewal due for the rescue boat engine starting battery to ensure emergency readiness and compliance with SOLAS regulations.','["Insulated electrical gloves","Safety goggles","FR coveralls"]','["Insulated spanners (13mm)","Wire brush","Digital multimeter","Petroleum jelly"]','Step-by-step standard procedure for safely isolating, removing, and installing a new starting battery for the rescue boat engine, followed by post-installation operational testing.','approved',1,'2026-08-25 15:45:27');
INSERT OR IGNORE INTO "guides" ("id","equipment_id","title","author_email","author_phone","symptom","safety_ppe","tools_required","introduction","status","is_approved","created_at") VALUES('959891d7-a81a-40e8-a514-beb235ae061f','16fe7e54-1192-4e49-99d8-90e1ca839614','Star Cool Reefer Temperature Not Pulling Down - No alarm','dhanushkumar.chandrasekaran1@gmail.com','9092391398','Reefer fails to pull down to setpoint (stuck at return -13.4°C, supply -14.3°C against a setpoint of -24.0°C). Compressor runs continuously at high speed with abnormally elevated suction pressure (0.3–0.4 bar) and lower-than-normal discharge pressure (~9.4 bar), with no alarms triggered.','["Safety glasses","Cryogenic/refrigerant handling gloves","Insulated hand tools","Safety footwear","FR overall"]','["Solenoid valve tester (magnetic indicator)","Digital clamp meter","Contact temperature probe / Inframeter","Refrigerant recovery unit & manifold gauge set","Spanner set"]','Systematic troubleshooting procedure for investigating poor cooling performance on a Star Cool container unit. This guide walks through checking compressor valve integrity, evaporator heating circuits, and refrigerant line valves step-by-step to isolate the root cause and restore normal operation.','approved',1,'2026-08-25 17:48:46');
INSERT OR IGNORE INTO "guides" ("id","equipment_id","title","author_email","author_phone","symptom","safety_ppe","tools_required","introduction","status","is_approved","created_at") VALUES('5952c265-c9cd-42b9-82db-9ce481f623ee','eq-pgd-msb','MSB Cargo Hold Feeder Breaker – Emergency Stop Trip & Status Indication Troubleshooting','dhanushkumar.chandrasekaran1@gmail.com','9092391398','During routine testing/inspection of the Cargo Hold Ventilation Emergency Stop from the Fire Control Station, one cargo hold feeder breaker failed to show tripped status and continued indicating "BREAKER ON / CLOSED" on the remote monitoring panel.','["Insulated electrical gloves","FR coveralls"]','["multimeter","screw driver"]','During a safety inspection, the Cargo Holds Reefer & Ventilation Emergency Stop (GR 3) switch at the Fire Control Station (FCS) was tested to ensure remote shutdown of all cargo hold ventilation and deck reefer supplies. Upon activation, all associated feeder circuit breakers tripped correctly as expected, except for feeder breaker PS115 (Bay 44 Hold), which failed to trip and continued displaying an active green "C.B. CLOSED" status indication on the remote control panel. This guide details the systematic diagnostic procedure used to investigate, isolate, and rectify the issue.','approved',1,'2026-08-25 20:11:57');
INSERT OR IGNORE INTO "guides" ("id","equipment_id","title","author_email","author_phone","symptom","safety_ppe","tools_required","introduction","status","is_approved","created_at") VALUES('b8b05563-fd28-49b5-9c51-0cdef507d8c0','eq-me-safety-omd','Main Engine Graviner Mk6 Oil Mist Detector (OMD) High Density Alarm','dhanushkumar.chandrasekaran1@gmail.com','9092391398','During Main Engine maneuvering, a sudden high oil mist density alarm triggered on the Alarm Monitoring System (AMS) (ME OILMIST DENSITY IN CRANKCASE / HIGH ALM), automatically initiating an emergency non-cancellable engine slowdown (ME NON CANCELLABLE SLD ACTIVE). Although the alarm cleared upon reset, optical sensor window contamination was suspected, requiring physical isolation, inspection, and lens cleaning before departure.','["Anti-static wrist strap (ESD safety)","Insulated safety shoes","Safety helmet","Safety glasses","Clean cotton gloves","Ear protection"]','["Official Graviner Mk6/Mk7 Service Kit (P/N D9221-027)","Electrolube GLC/ASC Glass Cleaner Fluid (500ml)","Graviner Foam Buds (lint-free)","4mm Hexagon key (Allen key)","Graviner Fan Retaining Plug Pulling Tool","Replacement base O-ring seals"]',replace('High oil mist concentration alarms during maneuvering represent a critical safety event that triggers automatic engine slowdowns to prevent potential crankcase explosions. \n\nWhen such alarms clear intermittently upon reset, the root cause is frequently optical sensor obscuration caused by baked-on oil splash, carbon haze, or condensation on the detector head lens rather than a mechanical bearing failure. \n\nThis guide outlines the end-to-end procedure for isolating the Graviner Mk6 OMD, safely removing the detector head without triggering false shutdowns, performing non-destructive optical lens cleaning using the maker''s approved service kit, and verifying sensor health via diagnostics.','\n',char(10)),'approved',1,'2026-08-27 16:08:08');

INSERT OR IGNORE INTO "guide_steps" ("id","guide_id","step_number","title","instruction","warning","images","created_at") VALUES('83990521-5f28-4f70-8240-b38696d57ff6','eb134d2a-210e-4e52-a487-a5b4a7b9ee58',1,'Inspect and comparison','Verify the new battery specifications match engine maker requirements (rated Ah, CCA, and terminal layout). Measure open-circuit voltage with a multimeter (must be 12.6V) and perform a battery load/CCA conduct-tester check to confirm 100% State of Health (SOH) before carrying it to the boat.',NULL,'[]','2026-08-25 15:45:27');
INSERT OR IGNORE INTO "guide_steps" ("id","guide_id","step_number","title","instruction","warning","images","created_at") VALUES('6fa49506-95f8-4dfb-8e5a-0049e999c5a4','eb134d2a-210e-4e52-a487-a5b4a7b9ee58',2,'Power Isolation','Switch off the rescue boat main battery isolator switch and ensure the battery charger supply is disconnected. Open the battery box or compartment cover to allow proper ventilation.','Ensure no naked flames or smoking nearby; battery compartments may contain explosive hydrogen gas.','[{"url":"/api/upload?key=1787672699259-IMG_20260821_111735.webp","isPdf":false,"name":"IMG_20260821_111735.webp"},{"url":"/api/upload?key=1787672702912-IMG_20260821_111739.webp","isPdf":false,"name":"IMG_20260821_111739.webp"},{"url":"/api/upload?key=1787672706209-IMG_20260821_111746.webp","isPdf":false,"name":"IMG_20260821_111746.webp"}]','2026-08-25 15:45:27');
INSERT OR IGNORE INTO "guide_steps" ("id","guide_id","step_number","title","instruction","warning","images","created_at") VALUES('4ccbbf52-b192-4257-ae4c-771dd9d3205a','eb134d2a-210e-4e52-a487-a5b4a7b9ee58',3,'Disconnect Old Battery',replace('Disconnect the Negative (-) black cable first using an insulated spanner, followed by the Positive (+) red cable. Unbolt and remove the battery holding bracket/clamp.\nCarefully lift out the old battery. Clean the battery tray of any dirt or residue. Place the new battery in the correct terminal orientation and secure it firmly with the holding clamp.','\n',char(10)),'Always disconnect the Negative terminal first to avoid accidental short circuits and spark generation when tools contact the metal frame.','[{"url":"/api/upload?key=1787672713691-IMG_20260821_111907.webp","isPdf":false,"name":"IMG_20260821_111907.webp"},{"url":"/api/upload?key=1787672717710-IMG_20260821_111920.webp","isPdf":false,"name":"IMG_20260821_111920.webp"},{"url":"/api/upload?key=1787672720777-IMG_20260821_112604.webp","isPdf":false,"name":"IMG_20260821_112604.webp"}]','2026-08-25 15:45:27');
INSERT OR IGNORE INTO "guide_steps" ("id","guide_id","step_number","title","instruction","warning","images","created_at") VALUES('d933301f-869e-4999-ad4d-ac4894628b06','eb134d2a-210e-4e52-a487-a5b4a7b9ee58',4,'Replace and Connecting Battery Terminals','Connect the Positive (+) red terminal first and tighten securely. Next, connect the Negative (-) black terminal. Apply a thin layer of petroleum jelly (Vaseline) over the terminals to prevent corrosion.','Do not overtighten the terminal bolts to avoid cracking the battery posts or casing.','[{"url":"/api/upload?key=1787672725976-IMG_20260821_115505.webp","isPdf":false,"name":"IMG_20260821_115505.webp"}]','2026-08-25 15:45:28');
INSERT OR IGNORE INTO "guide_steps" ("id","guide_id","step_number","title","instruction","warning","images","created_at") VALUES('a37ec71f-414f-4f8e-a49a-11e32f2a8d34','eb134d2a-210e-4e52-a487-a5b4a7b9ee58',5,'Testing','Turn ON the main battery isolator switch. Check the voltage reading on the multimeter or console gauge (12.6V–13.2V). Perform an engine test crank to ensure proper starting capability and verify that the charging system is functioning.','Ensure the propeller area is clear and engine cooling water supply is available before cranking the engine.','[]','2026-08-25 15:45:28');
INSERT OR IGNORE INTO "guide_steps" ("id","guide_id","step_number","title","instruction","warning","images","created_at") VALUES('94f042f6-5415-4c48-8d79-506df6266f60','959891d7-a81a-40e8-a514-beb235ae061f',1,'Record Operating Parameters & Assess System State','Record setpoint (-24.0°C), return (-13.4°C), supply (-14.3°C), suction pressure (0.3–0.4 bar), and discharge pressure (~9.4 bar). Note that suction pressure remaining elevated during full-speed compressor operation indicates either an valve leak, or an unexpected thermal load entering the low side.','Keep hands clear of moving condenser and evaporator fan assemblies.','[{"url":"/api/upload?key=1787680081560-IMG_20260820_140739.webp","isPdf":false,"name":"IMG_20260820_140739.webp"},{"url":"/api/upload?key=1787680083754-IMG_20260820_140745.webp","isPdf":false,"name":"IMG_20260820_140745.webp"}]','2026-08-25 17:48:46');
INSERT OR IGNORE INTO "guide_steps" ("id","guide_id","step_number","title","instruction","warning","images","created_at") VALUES('a13ab5b7-3d7f-4404-a223-ae30cd7f5640','959891d7-a81a-40e8-a514-beb235ae061f',2,'Check Low-Pressure (LP) Valve Plate & Compressor Health','Inspect the compressor suction valve plate and scroll mechanism for internal blow-by or mechanical damage that could cause elevated suction pressure. In this case, the LP valve plate is in good condition.','Isolate main 3-phase power before opening or inspecting electrical and mechanical enclosures.','[]','2026-08-25 17:48:46');
INSERT OR IGNORE INTO "guide_steps" ("id","guide_id","step_number","title","instruction","warning","images","created_at") VALUES('94682284-fdae-405e-b2b5-7d9ac1f641e3','959891d7-a81a-40e8-a514-beb235ae061f',3,'Inspect Evaporator Heating System','Check if the electric defrost heaters are accidentally energized during cooling mode. Put the unit into manual test mode, visually verify that the heater contactor is physically disengaged, and use a clamp meter to confirm zero current draw on the heater circuit.','Use insulated multimeter probes and PPE when checking live control panel terminals.','[]','2026-08-25 17:48:46');
INSERT OR IGNORE INTO "guide_steps" ("id","guide_id","step_number","title","instruction","warning","images","created_at") VALUES('9bfb6594-7897-4708-adcc-796aed9cd84c','959891d7-a81a-40e8-a514-beb235ae061f',4,'Inspect Hot Gas Defrost Solenoid Valve Operation','Feel the inlet and outlet pipes of the hot gas defrost valve while running in cooling mode. If the outlet line is hot during normal cooling, use a magnetic solenoid tester on the coil. If the coil is de-energized (no magnetic field) but the line remains hot, the internal valve plunger is mechanically stuck in the open position, bypassing hot discharge gas directly into the evaporator.','Hot gas refrigerant lines can exceed 80°C; do not touch with bare hands.','[{"url":"/api/upload?key=1787680086671-IMG_20260821_090848.webp","isPdf":false,"name":"IMG_20260821_090848.webp"},{"url":"/api/upload?key=1787680089056-IMG_20260825_105124.webp","isPdf":false,"name":"IMG_20260825_105124.webp"},{"url":"/api/upload?key=1787680091356-IMG_20260825_091002.webp","isPdf":false,"name":"IMG_20260825_091002.webp"}]','2026-08-25 17:48:46');
INSERT OR IGNORE INTO "guide_steps" ("id","guide_id","step_number","title","instruction","warning","images","created_at") VALUES('b8327c18-3740-43fa-bed0-cbe2ba1760eb','959891d7-a81a-40e8-a514-beb235ae061f',5,'Manual Actuation Attempt Using Permanent Magnet','Remove the solenoid coil from the valve stem and place a strong manual operating permanent magnet (solenoid service magnet) directly over the stem to manually lift and cycle the internal plunger. If the valve does not respond or the outlet line remains hot without any audible/tactile internal movement, it confirms the plunger is mechanically jammed/stuck internally in the open position and requires physical overhaul/replacement.',NULL,'[{"url":"/api/upload?key=1787680093802-IMG_20260825_094425.webp","isPdf":false,"name":"IMG_20260825_094425.webp"},{"url":"/api/upload?key=1787680096162-IMG_20260825_094430.webp","isPdf":false,"name":"IMG_20260825_094430.webp"}]','2026-08-25 17:48:46');
INSERT OR IGNORE INTO "guide_steps" ("id","guide_id","step_number","title","instruction","warning","images","created_at") VALUES('9535de7e-c0de-485a-808d-c54180dc1cf1','959891d7-a81a-40e8-a514-beb235ae061f',6,'Isolate, Replace Faulty Hot Gas Valve & Recover System','Pump down or recover refrigerant from the local line. Unbolt the stuck hot gas valve assembly, inspect the internal seat for contamination or mechanical seizure, and install a new replacement valve with fresh seals.',NULL,'[]','2026-08-25 17:48:46');
INSERT OR IGNORE INTO "guide_steps" ("id","guide_id","step_number","title","instruction","warning","images","created_at") VALUES('0d5bed98-25fa-4e4a-8940-79b7d4683da8','959891d7-a81a-40e8-a514-beb235ae061f',7,'System Pump Down & Triple Valve Isolation',replace('While the compressor is running, close the main liquid line shut-off valve on the receiver bottle to pump down the refrigerant charge into the receiver.\n\nMonitor the suction pressure on the display. Once the pressure drops close to -0.1 bar (or slight vacuum), immediately shut down the unit.\n\nFor complete 100% positive isolation before opening the line, fully front-seat (close) all three critical service valves:\n\nSuction Service Valve\n\nDischarge Service Valve\n\nEconomizer Service Valve\n\nPump Down Operation: While the compressor is running in cooling mode, fully close the liquid line outlet valve on the receiver bottle. The compressor will draw the entire refrigerant charge from the system and store it inside the receiver.\n\nTrip / Shutdown Point: Monitor the suction gauge on the controller. When suction pressure drops near 0.1 to 0.0 bar, immediately turn off the compressor switch to prevent pulling into deep vacuum or overheating.\n\nPositive Triple Valve Isolation: Fully close (front-seat) the Suction Service Valve, Discharge Service Valve, and Economizer Service Valve to create a complete safety envelope around the compressor and hot gas bypass loop.','\n',char(10)),'Ensure all three service valves are fully closed to prevent trapped high-pressure refrigerant from blowing back during disassembly.','[{"url":"/api/upload?key=1787680098777-IMG_20260825_092909.webp","isPdf":false,"name":"IMG_20260825_092909.webp"},{"url":"/api/upload?key=1787680101713-IMG_20260825_092929.webp","isPdf":false,"name":"IMG_20260825_092929.webp"},{"url":"/api/upload?key=1787680104036-IMG_20260825_094828.webp","isPdf":false,"name":"IMG_20260825_094828.webp"},{"url":"/api/upload?key=1787680106489-IMG_20260825_094831.webp","isPdf":false,"name":"IMG_20260825_094831.webp"},{"url":"/api/upload?key=1787680108670-IMG_20260825_094836.webp","isPdf":false,"name":"IMG_20260825_094836.webp"}]','2026-08-25 17:48:46');
INSERT OR IGNORE INTO "guide_steps" ("id","guide_id","step_number","title","instruction","warning","images","created_at") VALUES('5edb8a59-11e7-4483-a3cb-b9ab10b6439c','959891d7-a81a-40e8-a514-beb235ae061f',8,'Disassembly & Plunger Replacement','Verify zero residual pressure in the isolated section using a manifold gauge. Use an appropriate Torx key/socket to unbolt the valve bonnet/sleeve from the valve body. Extract the stuck internal plunger, clean the valve body seat of any debris or varnish, and install a brand-new replacement plunger kit with fresh seals. Retorque the bonnet securely.','Wear cryogenic gloves and a face shield when cracking the valve body open to avoid contact with residual refrigerant or oil mist.','[{"url":"/api/upload?key=1787680110884-IMG_20260821_090852.webp","isPdf":false,"name":"IMG_20260821_090852.webp"},{"url":"/api/upload?key=1787680113157-IMG_20260821_090912.webp","isPdf":false,"name":"IMG_20260821_090912.webp"},{"url":"/api/upload?key=1787680115482-IMG_20260825_103150.webp","isPdf":false,"name":"IMG_20260825_103150.webp"},{"url":"/api/upload?key=1787680117311-IMG_20260825_104256.webp","isPdf":false,"name":"IMG_20260825_104256.webp"}]','2026-08-25 17:48:46');
INSERT OR IGNORE INTO "guide_steps" ("id","guide_id","step_number","title","instruction","warning","images","created_at") VALUES('5d7d6b2f-2ab7-460d-8f31-b00141c905b5','959891d7-a81a-40e8-a514-beb235ae061f',9,'Operational Verification',replace('Start the reefer unit and allow it to run in stable cooling mode.\n\nRefrigerant Level Check & Top-Up: Since the residual freon trapped inside the isolated pipe section was vented/lost during valve removal, the system charge level will be slightly reduced. Observe the liquid line sight glass during steady compressor operation:\n\nIf continuous vapor bubbles are visible in the sight glass, slowly top up the appropriate refrigerant (as per unit nameplate spec, e.g., R134a) in liquid phase via the suction charging port until the sight glass runs completely clear/solid liquid.\n\nConfirm that the hot gas valve outlet pipe remains cold, suction pressure normalizes, and the container temperature pulls down steadily toward -24.0°C.','\n',char(10)),NULL,'[{"url":"/api/upload?key=1787680119650-IMG_20260825_105124.webp","isPdf":false,"name":"IMG_20260825_105124.webp"},{"url":"/api/upload?key=1787680121891-IMG_20260825_135005.webp","isPdf":false,"name":"IMG_20260825_135005.webp"},{"url":"/api/upload?key=1787680124256-IMG_20260825_104139.webp","isPdf":false,"name":"IMG_20260825_104139.webp"}]','2026-08-25 17:48:46');
INSERT OR IGNORE INTO "guide_steps" ("id","guide_id","step_number","title","instruction","warning","images","created_at") VALUES('04e7ddc0-3402-4c81-a974-ebd1c8d2142b','5952c265-c9cd-42b9-82db-9ce481f623ee',1,'Activate FCS Emergency Stop (GR 3) & Verify Remote Panel Status',replace('CARGO HOLDS REEFER & VENT. rotary emergency switch to the OFF / TRIP (0) position at the Fire Control Station (FCS). Proceed to the remote monitoring mimicked panel and verify breaker status indications:\n\nConfirm whether all hold and reefer feeder breakers indicate C.B. OPEN (Red lamp).\n\nIdentify that breaker PS115 (Bay 44 Hold) fails to respond to the trip command, maintaining its illuminated green "C.B. CLOSED" indication, confirming a trip circuit or breaker mechanism failure.','\n',char(10)),'Inform the duty engineer and deck team before carrying out emergency stop trips to avoid unexpected stoppage of operational cargo machinery.','[{"url":"/api/upload?key=1787688687424-IMG_20260725_083705.webp","isPdf":false,"name":"IMG_20260725_083705.webp"},{"url":"/api/upload?key=1787688689961-IMG_20260825_210717.webp","isPdf":false,"name":"IMG_20260825_210717.webp"},{"url":"/api/upload?key=1787688692521-IMG_20260825_210720.webp","isPdf":false,"name":"IMG_20260825_210720.webp"},{"url":"/api/upload?key=1787688694828-IMG_20260825_210728.webp","isPdf":false,"name":"IMG_20260825_210728.webp"},{"url":"/api/upload?key=1787688697186-IMG_20260825_210739.webp","isPdf":false,"name":"IMG_20260825_210739.webp"}]','2026-08-25 20:11:57');
INSERT OR IGNORE INTO "guide_steps" ("id","guide_id","step_number","title","instruction","warning","images","created_at") VALUES('f7bd86ee-c4e0-4669-be85-a2da229dea70','5952c265-c9cd-42b9-82db-9ce481f623ee',2,'Locate & Trace Circuit Schematic for Emergency Stop Panel',replace('Open the Fire Station Control Panel / Emergency Stop Panel Connection Diagram:\n\nLocate the GROUP 3: CARGO HOLDS REEFER & VENTILATION section on the drawing.\n\nTrace the line for PS115 (Column 10), noting the 440V supply connection from panel PS57-02 to terminals X02:1 and X02:2 via cable 14940481.\n\nMap the trip loop sequence through relay contact -K2.91, terminal block -X3:127, FSCP intermediate terminals -X7:57 / -X7:58, and junction block terminals -X3:137 / -X3:138.\n\nUse this terminal path to systematically check voltage drops and switch continuity at the panel.','\n',char(10)),'Verify terminal block numbers carefully against the schematic before testing; the control loop carries live 440V AC line voltage.','[{"url":"/api/upload?key=1787688701298-cargo%20hold%20vent%20emg%20stop%20trouble%20shooting.pdf","isPdf":true,"name":"cargo hold vent emg stop trouble shooting.pdf"}]','2026-08-25 20:11:57');
INSERT OR IGNORE INTO "guide_steps" ("id","guide_id","step_number","title","instruction","warning","images","created_at") VALUES('57e7ffcb-f0bb-44d5-a6ca-40f3eea021dd','5952c265-c9cd-42b9-82db-9ce481f623ee',3,'Rotary Emergency Stop Switch Contact Verification : Inspect Emergency Switch Contact (Terminals 29 & 30 / -S3.3)',replace('Although -S3.3 serves as the common rotary Emergency Stop switch for the group, each feeder breaker path operates through dedicated internal contact blocks.\n\nOpen the rear enclosure of the Fire Station Control Panel (FCSP) to access the switch contact bank.\n\nUse a digital multimeter to test continuity across contacts 29 & 30 while toggling the switch between NORMAL (1) and TRIP (0) positions.\n\nConfirm whether the contact block physically opens its circuit upon rotation or remains welded/mechanically closed.','\n',char(10)),NULL,'[]','2026-08-25 20:11:57');
INSERT OR IGNORE INTO "guide_steps" ("id","guide_id","step_number","title","instruction","warning","images","created_at") VALUES('0ec4accd-73e1-4105-af21-791fea725a3f','5952c265-c9cd-42b9-82db-9ce481f623ee',4,'Disconnect Terminal 29 & 30 Wiring to Rule Out Switch Failure',replace('To eliminate the possibility of a damaged or stuck internal contact inside the rotary switch, physically disconnect the control wires from terminals 29 and 30 (Switch -S3.3 / -S52 path) inside the FSCP panel.\n\nWith the circuit completely opened physically, observe the breaker status on the panel.\n\nNote that despite the manual wire disconnection (guaranteed open circuit), breaker PS115 still failed to trip and remained closed.\n\nThis confirms that the fault is not located within the Fire Control Station rotary switch itself, but further downstream toward the switchboard panel PS57-02, relay -K2.90, S52 or the breaker trip unit.','\n',char(10)),'Insulate the disconnected wire ends with electrical insulation tape to avoid short circuits against the panel metal casing or adjacent live terminals.','[]','2026-08-25 20:11:57');
INSERT OR IGNORE INTO "guide_steps" ("id","guide_id","step_number","title","instruction","warning","images","created_at") VALUES('df92816f-2683-43b1-ac74-b1972b885206','5952c265-c9cd-42b9-82db-9ce481f623ee',5,'Inspect Control Sub-Panel PS57.02',replace('Proceed to the lower control compartment beneath the ABB SACE E2 Air Circuit Breaker (Panel PS57.02 / PS115 REEFER DISTRIBUTION SWBD):\n\nOpen the terminal enclosure housing terminal strip -X02 \n\nInspect incoming emergency stop loop terminals -X02:1 and -X02:2.\n\nIdentify that an unauthorized bypass wire (black coiled jumper lead) is connected across terminals -X02:1 and -X02:2, hardwiring the control loop and completely bypassing the remote Emergency Stop signal from the Fire Control Station.','\n',char(10)),'Verify control voltage with a multimeter before touching terminal screws inside the -X02 terminal strip; terminals carry live 440V/230V control supply.','[{"url":"/api/upload?key=1787688703821-IMG_20260725_144446.webp","isPdf":false,"name":"IMG_20260725_144446.webp"},{"url":"/api/upload?key=1787688706159-IMG_20260725_144452.webp","isPdf":false,"name":"IMG_20260725_144452.webp"},{"url":"/api/upload?key=1787688708736-IMG_20260725_144656.webp","isPdf":false,"name":"IMG_20260725_144656.webp"},{"url":"/api/upload?key=1787688711523-IMG_20260725_144756.webp","isPdf":false,"name":"IMG_20260725_144756.webp"}]','2026-08-25 20:11:57');
INSERT OR IGNORE INTO "guide_steps" ("id","guide_id","step_number","title","instruction","warning","images","created_at") VALUES('e1cc45eb-35be-4a53-8211-29f5f41799a4','5952c265-c9cd-42b9-82db-9ce481f623ee',6,'Remove Jumper Wire, Restore Circuitry & Verify Breaker Trip',replace('physically loosen screws on terminals -X02:1 and -X02:2.\n\nRemove the jumper wire completely and reconnect the original remote emergency stop trip loop leads securely into terminals -X02:1 and -X02:2.  \n\nre-test the Emergency Stop switch from the Fire Control Station.\n\nVerify that the circuit breaker PS115 trips immediately (mechanical indicator changes to OFF / Discharged), and the remote monitoring console status updates correctly to C.B. OPEN (Red indication).','\n',char(10)),NULL,'[{"url":"/api/upload?key=1787688713620-IMG_20260725_144650.webp","isPdf":false,"name":"IMG_20260725_144650.webp"},{"url":"/api/upload?key=1787688716163-IMG_20260825_210728.webp","isPdf":false,"name":"IMG_20260825_210728.webp"}]','2026-08-25 20:11:57');
INSERT OR IGNORE INTO "guide_steps" ("id","guide_id","step_number","title","instruction","warning","images","created_at") VALUES('f1817031-67a6-46fd-b2a3-04ef7a1b5ff1','b8b05563-fd28-49b5-9c51-0cdef507d8c0',1,'Isolate Target Cylinder Detector & Safety Relays on OMD Control Panel',replace('Access the Graviner Mk6 OMD Control Panel, press Main Menu, enter Engineer Mode, and navigate to 3. Isolate. \n\nUnder the Isolate Menu, select 3. Relay and set it to ISOLATE to prevent inadvertent slowdown/shutdown trip signals from transmitting to the AMS during maintenance.\n\nSelect 2. Detector, choose the specific cylinder detector head that triggered the alarm, and set its state to ISO (Isolate).  \n\nConfirm that the Isolate and Detector Isolate LEDs illuminate on the panel faceplate.  \n\n(Refer to the attached step photos and the full Graviner maintenance manual PDF for the complete menu navigation sequence and parameter details).','\n',char(10)),'Always isolate the shutdown/slowdown relays and the specific detector head before physically removing sensor hardware to avoid triggering emergency engine trips or false backup alarms.','[{"url":"/api/upload?key=1787845471209-IMG_20260825_144420.webp","isPdf":false,"name":"IMG_20260825_144420.webp"},{"url":"/api/upload?key=1787845483775-IMG_20260825_152530.webp","isPdf":false,"name":"IMG_20260825_152530.webp"},{"url":"/api/upload?key=1787845489574-IMG_20260825_152534.webp","isPdf":false,"name":"IMG_20260825_152534.webp"},{"url":"/api/upload?key=1787845494306-IMG_20260825_152546.webp","isPdf":false,"name":"IMG_20260825_152546.webp"},{"url":"/api/upload?key=1787845498704-IMG_20260825_152556.webp","isPdf":false,"name":"IMG_20260825_152556.webp"},{"url":"/api/upload?key=1787845502013-IMG_20260825_152558.webp","isPdf":false,"name":"IMG_20260825_152558.webp"},{"url":"/api/upload?key=1787845505826-IMG_20260825_152615.webp","isPdf":false,"name":"IMG_20260825_152615.webp"},{"url":"/api/upload?key=1787845508807-IMG_20260825_152619.webp","isPdf":false,"name":"IMG_20260825_152619.webp"},{"url":"/api/upload?key=1787845512141-IMG_20260825_152639.webp","isPdf":false,"name":"IMG_20260825_152639.webp"},{"url":"/api/upload?key=1787845515321-IMG_20260825_152713.webp","isPdf":false,"name":"IMG_20260825_152713.webp"},{"url":"/api/upload?key=1787845519047-IMG_20260825_152718.webp","isPdf":false,"name":"IMG_20260825_152718.webp"}]','2026-08-27 16:08:09');
INSERT OR IGNORE INTO "guide_steps" ("id","guide_id","step_number","title","instruction","warning","images","created_at") VALUES('c8fad53b-3660-448a-a274-3d87f46d2064','b8b05563-fd28-49b5-9c51-0cdef507d8c0',2,'Disconnect Top Cable & Remove Detector Head from Mounting Base',replace('Proceed to the engine side and locate the specific cylinder compartment detector identified in the fault log.\n\nUsing a 4mm hexagon key (Allen key), loosen the two captive fixing screws securing the Detector Head to the base unit.\n\nCarefully lift the Detector Head vertically off the base and place it inverted on a clean workbench to access the internal sampling fan and optical chamber.\n\nInspect the detector base O-ring seal for signs of wear, oil perishing, or improper seating.','\n',char(10)),'Never remove the detector head while the engine is running to prevent hot crankcase oil spray or vapor blow-out. Observe anti-static precautions when handling the detector unit.','[{"url":"/api/upload?key=1787845523834-IMG_20260825_153004.webp","isPdf":false,"name":"IMG_20260825_153004.webp"},{"url":"/api/upload?key=1787845528338-IMG_20260825_153022.webp","isPdf":false,"name":"IMG_20260825_153022.webp"},{"url":"/api/upload?key=1787845532198-IMG_20260825_153103.webp","isPdf":false,"name":"IMG_20260825_153103.webp"},{"url":"/api/upload?key=1787845536018-IMG_20260825_153123.webp","isPdf":false,"name":"IMG_20260825_153123.webp"},{"url":"/api/upload?key=1787845539835-IMG_20260825_153130.webp","isPdf":false,"name":"IMG_20260825_153130.webp"}]','2026-08-27 16:08:09');
INSERT OR IGNORE INTO "guide_steps" ("id","guide_id","step_number","title","instruction","warning","images","created_at") VALUES('e3ce61d0-7bb7-4110-b290-2a06e225aa76','b8b05563-fd28-49b5-9c51-0cdef507d8c0',3,'Extract Fan Retaining Plug Using Dedicated Graviner Pulling Tool',replace('Invert the removed Detector Head to expose the small internal sampling fan and mounting springs.  \n\nUse the dedicated Graviner Pulling Tool (wooden-handled extractor tool from the service kit).  \n\nSlide the hollow tip of the tool over the nylon Fan Retaining Plug, engage the shoulder groove, and gently pull straight out to release the plug. \n \nCarefully lift the sampling fan clear of its 4 support compression springs.  \n\nInspect the retaining plug and compression springs for deformation, cracking, or damage before proceeding to the optics cleaning','\n',char(10)),'Never pull or apply direct force to the center sticker of the fan housing; handle the fan solely by its outer plastic frame to prevent bearing and blade damage. Take extreme caution not to drop or lose the small compression springs and nylon plug.','[{"url":"/api/upload?key=1787845543591-IMG_20260825_153218.webp","isPdf":false,"name":"IMG_20260825_153218.webp"},{"url":"/api/upload?key=1787845547044-IMG_20260825_153223.webp","isPdf":false,"name":"IMG_20260825_153223.webp"},{"url":"/api/upload?key=1787845551451-IMG_20260825_153314.webp","isPdf":false,"name":"IMG_20260825_153314.webp"}]','2026-08-27 16:08:09');
INSERT OR IGNORE INTO "guide_steps" ("id","guide_id","step_number","title","instruction","warning","images","created_at") VALUES('e284899b-4e0f-4887-9988-cf8df8253a68','b8b05563-fd28-49b5-9c51-0cdef507d8c0',4,'Clean Optical Sensor Chamber & Glass Ring Using Maker-Approved Foam Buds',replace('Take a fresh, lint-free foam bud from the Graviner cleaning kit and apply official Electrolube GLC / ASC Glass Cleaner Fluid.  \n\nCarefully insert the foam bud into the central oil mist detection opening of the Detector Head.  \n\nGently rotate and wipe around the internal glass ring, optical sensor aperture, and the test LED to remove accumulated oil mist film and carbon deposits.  \n\nRepeat the cleaning process a second time using a new foam bud to guarantee zero streaks or chemical residue remain on the glass chamber.  \n\nWipe clean the surrounding base body cavity and check that no loose fibers or dirt remain inside the sampling path.','\n',char(10)),'Never use generic electrical contact cleaners, WD-40, acetone, or standard isopropyl alcohol, as aggressive solvents will permanently haze or damage the precision optical glass coating. On older detector heads, take extra care not to stress the exposed test LED PCB.','[]','2026-08-27 16:08:09');

