INSERT OR IGNORE INTO "guide_images" ("id","guide_id","caption","url","order_index","created_at") VALUES('100009bb-7c46-484c-ad19-c19fe79c463e','b8b05563-fd28-49b5-9c51-0cdef507d8c0','OMD TN18001 Cleaning the Graviner Detector Head v1.pdf','/api/upload?key=1787846884628-OMD%20TN18001%20Cleaning%20the%20Graviner%20Detector%20Head%20v1.pdf',1,'2026-08-27 16:08:09');